from pathlib import Path

from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import KeepTogether, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

from app.core.config import get_settings
from app.models import Document


class ReportGenerator:
    """Produces a self-contained, printable verification report."""

    def generate(self, document: Document) -> Path:
        output = get_settings().report_dir / f"verification-{document.id}.pdf"
        styles = getSampleStyleSheet()
        styles.add(ParagraphStyle(name="Small", parent=styles["BodyText"], fontSize=8, leading=11, textColor=colors.HexColor("#475569")))
        styles.add(ParagraphStyle(name="ReportTitle", parent=styles["Title"], fontSize=23, leading=27, textColor=colors.HexColor("#0F172A"), spaceAfter=4))
        styles.add(ParagraphStyle(name="Heading", parent=styles["Heading2"], fontSize=13, leading=16, textColor=colors.HexColor("#0F766E"), spaceBefore=12, spaceAfter=5))
        doc = SimpleDocTemplate(str(output), pagesize=A4, rightMargin=16*mm, leftMargin=16*mm, topMargin=15*mm, bottomMargin=15*mm, title="VeriSight Verification Report")
        story = [Paragraph("VeriSight", styles["Heading1"]), Paragraph("Document Verification Report", styles["ReportTitle"]), Paragraph(f"Report ID: {document.id}<br/>Generated: {document.verified_at.strftime('%d %b %Y, %H:%M UTC') if document.verified_at else 'Pending'}", styles["Small"]), Spacer(1, 7*mm)]
        status_color = colors.HexColor("#15803D") if document.status.value == "verified" else colors.HexColor("#B45309")
        overview = [["Document", document.original_filename], ["Detected type", document.document_type.replace("_", " ").title()], ["Status", document.status.value.title()], ["Verification confidence", f"{document.confidence_score or 0}/100"], ["Estimated fraud risk", f"{document.fraud_probability or 0:.1f}%"], ["OCR confidence", f"{document.ocr_confidence or 0:.1f}%"]]
        table = Table(overview, colWidths=[51*mm, 112*mm])
        table.setStyle(TableStyle([("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#F1F5F9")), ("TEXTCOLOR", (0, 0), (0, -1), colors.HexColor("#334155")), ("TEXTCOLOR", (1, 2), (1, 2), status_color), ("FONTNAME", (0, 0), (-1, -1), "Helvetica"), ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"), ("FONTSIZE", (0, 0), (-1, -1), 9), ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("TOPPADDING", (0, 0), (-1, -1), 6), ("BOTTOMPADDING", (0, 0), (-1, -1), 6)]))
        story += [table, Paragraph("Assessment", styles["Heading"]), Paragraph(document.explanation or "No assessment is available.", styles["BodyText"])]
        fields = [["Field", "Extracted value"]] + [[key.replace("_", " ").title(), ", ".join(value) if isinstance(value, list) else str(value or "Not found")] for key, value in document.fields.items() if key != "detected_dates"]
        story += [Paragraph("Extracted fields", styles["Heading"]), Table(fields, colWidths=[55*mm, 108*mm], style=TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0F766E")), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white), ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"), ("GRID", (0, 0), (-1, -1), .3, colors.HexColor("#CBD5E1")), ("FONTSIZE", (0, 0), (-1, -1), 8.5), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("TOPPADDING", (0, 0), (-1, -1), 5), ("BOTTOMPADDING", (0, 0), (-1, -1), 5)]))]
        finding_rows = [["Severity", "Finding", "Evidence"]] + [[item["severity"].upper(), item["message"], ", ".join(f"{key}: {value}" for key, value in item.get("evidence", {}).items())] for item in document.findings]
        if len(finding_rows) == 1:
            finding_rows.append(["INFO", "No suspicious finding generated by automated checks.", "Manual review remains recommended for high-stakes decisions."])
        story += [Paragraph("Automated forensic findings", styles["Heading"]), Table(finding_rows, colWidths=[22*mm, 88*mm, 53*mm], repeatRows=1, style=TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#334155")), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white), ("GRID", (0, 0), (-1, -1), .3, colors.HexColor("#CBD5E1")), ("FONTSIZE", (0, 0), (-1, -1), 8), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("TOPPADDING", (0, 0), (-1, -1), 5), ("BOTTOMPADDING", (0, 0), (-1, -1), 5)])), Spacer(1, 7*mm), Paragraph("Important: This automated report provides risk indicators, not a legal determination of authenticity. Use it alongside human review and issuer-side validation.", styles["Small"])]
        doc.build(story, onFirstPage=self._footer, onLaterPages=self._footer)
        return output

    @staticmethod
    def _footer(canvas, doc) -> None:
        canvas.saveState()
        canvas.setStrokeColor(colors.HexColor("#CBD5E1"))
        canvas.line(16*mm, 11*mm, A4[0]-16*mm, 11*mm)
        canvas.setFont("Helvetica", 7.5)
        canvas.setFillColor(colors.HexColor("#64748B"))
        canvas.drawString(16*mm, 7*mm, "VeriSight - confidential verification report")
        canvas.drawRightString(A4[0]-16*mm, 7*mm, f"Page {doc.page}")
        canvas.restoreState()
